        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg         valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p, g;
    wire [23:0] P0, G0, P1, G1, P2, G2, P3, G3, P4, G4;
    wire [23:0] c;
    wire [23:0] sum;

    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    genvar i;

    // Stage 0: stride 1
    generate
        for (i = 0; i < 24; i = i + 1) begin : st0
            if (i >= 1) begin
                assign G0[i] = g[i] | (p[i] & g[i-1]);
                assign P0[i] = p[i] & p[i-1];
            end else begin
                assign G0[i] = g[i];
                assign P0[i] = p[i];
            end
        end
    endgenerate

    // Stage 1: stride 2
    generate
        for (i = 0; i < 24; i = i + 1) begin : st1
            if (i >= 2) begin
                assign G1[i] = G0[i] | (P0[i] & G0[i-2]);
                assign P1[i] = P0[i] & P0[i-2];
            end else begin
                assign G1[i] = G0[i];
                assign P1[i] = P0[i];
            end
        end
    endgenerate

    // Stage 2: stride 4
    generate
        for (i = 0; i < 24; i = i + 1) begin : st2
            if (i >= 4) begin
                assign G2[i] = G1[i] | (P1[i] & G1[i-4]);
                assign P2[i] = P1[i] & P1[i-4];
            end else begin
                assign G2[i] = G1[i];
                assign P2[i] = P1[i];
            end
        end
    endgenerate

    // Stage 3: stride 8
    generate
        for (i = 0; i < 24; i = i + 1) begin : st3
            if (i >= 8) begin
                assign G3[i] = G2[i] | (P2[i] & G2[i-8]);
                assign P3[i] = P2[i] & P2[i-8];
            end else begin
                assign G3[i] = G2[i];
                assign P3[i] = P2[i];
            end
        end
    endgenerate

    // Stage 4: stride 16
    generate
        for (i = 0; i < 24; i = i + 1) begin : st4
            if (i >= 16) begin
                assign G4[i] = G3[i] | (P3[i] & G3[i-16]);
                assign P4[i] = P3[i] & P3[i-16];
            end else begin
                assign G4[i] = G3[i];
                assign P4[i] = P3[i];
            end
        end
    endgenerate

    // carry into bit i = cumulative generate up through bit i-1; carry-in to bit0 = 0
    assign c[0] = 1'b0;
    generate
        for (i = 1; i < 24; i = i + 1) begin : carry_gen
            assign c[i] = G4[i-1];
        end
    endgenerate

    assign sum = p ^ c;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg         valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p, g;
    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    wire [23:0] G1,P1,G2,P2,G3,P3,G4,P4,G5,P5;

    genvar i;

    // Level 0: group=2, half=1
    generate
        for (i = 0; i < 24; i = i + 1) begin: lvl0
            localparam integer GS = (i/2)*2;
            if ((i-GS) >= 1) begin
                localparam integer REF = GS;
                assign G1[i] = g[i] | (p[i] & g[REF]);
                assign P1[i] = p[i] & p[REF];
            end else begin
                assign G1[i] = g[i];
                assign P1[i] = p[i];
            end
        end
    endgenerate

    // Level 1: group=4, half=2
    generate
        for (i = 0; i < 24; i = i + 1) begin: lvl1
            localparam integer GS = (i/4)*4;
            if ((i-GS) >= 2) begin
                localparam integer REF = GS+1;
                assign G2[i] = G1[i] | (P1[i] & G1[REF]);
                assign P2[i] = P1[i] & P1[REF];
            end else begin
                assign G2[i] = G1[i];
                assign P2[i] = P1[i];
            end
        end
    endgenerate

    // Level 2: group=8, half=4
    generate
        for (i = 0; i < 24; i = i + 1) begin: lvl2
            localparam integer GS = (i/8)*8;
            if ((i-GS) >= 4) begin
                localparam integer REF = GS+3;
                assign G3[i] = G2[i] | (P2[i] & G2[REF]);
                assign P3[i] = P2[i] & P2[REF];
            end else begin
                assign G3[i] = G2[i];
                assign P3[i] = P2[i];
            end
        end
    endgenerate

    // Level 3: group=16, half=8
    generate
        for (i = 0; i < 24; i = i + 1) begin: lvl3
            localparam integer GS = (i/16)*16;
            if ((i-GS) >= 8) begin
                localparam integer REF = GS+7;
                assign G4[i] = G3[i] | (P3[i] & G3[REF]);
                assign P4[i] = P3[i] & P3[REF];
            end else begin
                assign G4[i] = G3[i];
                assign P4[i] = P3[i];
            end
        end
    endgenerate

    // Level 4: group=32 (covers all 24 bits, GS always 0), half=16
    generate
        for (i = 0; i < 24; i = i + 1) begin: lvl4
            localparam integer GS = 0;
            if ((i-GS) >= 16) begin
                localparam integer REF = 15;
                assign G5[i] = G4[i] | (P4[i] & G4[REF]);
                assign P5[i] = P4[i] & P4[REF];
            end else begin
                assign G5[i] = G4[i];
                assign P5[i] = P4[i];
            end
        end
    endgenerate

    wire [23:0] c;
    assign c[0] = 1'b0;
    generate
        for (i = 1; i < 24; i = i + 1) begin: cgen
            assign c[i] = G5[i-1];
        end
    endgenerate

    wire [23:0] sum = p ^ c;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    // Block-level generate/propagate for 6 blocks of 4 bits
    wire [5:0] G, P;

    genvar j;
    generate
        for (j = 0; j < 6; j = j + 1) begin : blk
            wire g0 = g[4*j+0];
            wire g1 = g[4*j+1];
            wire g2 = g[4*j+2];
            wire g3 = g[4*j+3];
            wire p0 = p[4*j+0];
            wire p1 = p[4*j+1];
            wire p2 = p[4*j+2];
            wire p3 = p[4*j+3];

            assign G[j] = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            assign P[j] = p0 & p1 & p2 & p3;
        end
    endgenerate

    // Block-level carry-ins via direct (parallel) sum-of-products lookahead
    wire [5:0] cin;
    assign cin[0] = 1'b0;
    assign cin[1] = G[0];
    assign cin[2] = G[1] | (P[1] & G[0]);
    assign cin[3] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
    assign cin[4] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);
    assign cin[5] = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]) | (P[4] & P[3] & P[2] & P[1] & G[0]);

    // Per-bit local carries resolved from block carry-in + local g/p
    wire [23:0] sum;
    generate
        for (j = 0; j < 6; j = j + 1) begin : sumblk
            wire g0 = g[4*j+0];
            wire g1 = g[4*j+1];
            wire g2 = g[4*j+2];
            wire p0 = p[4*j+0];
            wire p1 = p[4*j+1];
            wire p2 = p[4*j+2];

            wire c0 = cin[j];
            wire c1 = g0 | (p0 & c0);
            wire c2 = g1 | (p1 & g0) | (p1 & p0 & c0);
            wire c3 = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);

            assign sum[4*j+0] = p[4*j+0] ^ c0;
            assign sum[4*j+1] = p[4*j+1] ^ c1;
            assign sum[4*j+2] = p[4*j+2] ^ c2;
            assign sum[4*j+3] = p[4*j+3] ^ c3;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    // ---- Level 0: per-block (4-bit) generate/propagate ----
    wire [5:0] G0, P0;

    genvar j;
    generate
        for (j = 0; j < 6; j = j + 1) begin : blockGP
            wire g0 = g[4*j+0];
            wire g1 = g[4*j+1];
            wire g2 = g[4*j+2];
            wire g3 = g[4*j+3];
            wire p0 = p[4*j+0];
            wire p1 = p[4*j+1];
            wire p2 = p[4*j+2];
            wire p3 = p[4*j+3];

            assign G0[j] = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            assign P0[j] = p0 & p1 & p2 & p3;
        end
    endgenerate

    // ---- Block-level Kogge-Stone prefix tree over 6 elements ----
    wire [5:0] G1, P1, G2, P2, G3;

    generate
        for (j = 0; j < 6; j = j + 1) begin : lvl1
            if (j >= 1) begin
                assign G1[j] = G0[j] | (P0[j] & G0[j-1]);
                assign P1[j] = P0[j] & P0[j-1];
            end else begin
                assign G1[j] = G0[j];
                assign P1[j] = P0[j];
            end
        end
    endgenerate

    generate
        for (j = 0; j < 6; j = j + 1) begin : lvl2
            if (j >= 2) begin
                assign G2[j] = G1[j] | (P1[j] & G1[j-2]);
                assign P2[j] = P1[j] & P1[j-2];
            end else begin
                assign G2[j] = G1[j];
                assign P2[j] = P1[j];
            end
        end
    endgenerate

    generate
        for (j = 0; j < 6; j = j + 1) begin : lvl3
            if (j >= 4) begin
                assign G3[j] = G2[j] | (P2[j] & G2[j-4]);
            end else begin
                assign G3[j] = G2[j];
            end
        end
    endgenerate

    // Block carry-ins from full prefix tree
    wire [5:0] cin;
    assign cin[0] = 1'b0;
    generate
        for (j = 1; j < 6; j = j + 1) begin : cingen
            assign cin[j] = G3[j-1];
        end
    endgenerate

    // ---- Intra-block carry resolve + sum ----
    wire [23:0] sum;
    generate
        for (j = 0; j < 6; j = j + 1) begin : resolve
            wire g0 = g[4*j+0];
            wire g1 = g[4*j+1];
            wire g2 = g[4*j+2];
            wire p0 = p[4*j+0];
            wire p1 = p[4*j+1];
            wire p2 = p[4*j+2];
            wire p3 = p[4*j+3];

            wire c0 = cin[j];
            wire c1 = g0 | (p0 & c0);
            wire c2 = g1 | (p1 & g0) | (p1 & p0 & c0);
            wire c3 = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);

            assign sum[4*j+0] = p0 ^ c0;
            assign sum[4*j+1] = p1 ^ c1;
            assign sum[4*j+2] = p2 ^ c2;
            assign sum[4*j+3] = p3 ^ c3;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule
